JS='/* FSJ_INSTALL_CENTER_V1 */\n;(()=>{\nif(document.getElementById(\'fsjInstallCenter\'))return;\nconst login=document.getElementById(\'login\');if(!login)return;\nconst box=document.createElement(\'section\');box.id=\'fsjInstallCenter\';box.className=\'card\';\nbox.innerHTML=\'<h2>Instala\xe7\xe3o e atualiza\xe7\xe3o</h2><p id="fsjInstallMessage" role="status">Solicite autoriza\xe7\xe3o ao Propriet\xe1rio para liberar seu acesso.</p><button id="fsjInstallRequest" type="button">Solicitar autoriza\xe7\xe3o</button><button id="fsjInstallCheck" type="button">Consultar autoriza\xe7\xe3o</button><a id="fsjInstallPackage" class="download-app" href="/baixar/android" download="Assistente-FSJ-Reserva.apk" hidden>Instalar Android</a><button id="fsjInstallUpdate" type="button" hidden>Verificar atualiza\xe7\xe3o</button><p id="fsjInstallHelp">Instala\xe7\xe3o e atualiza\xe7\xe3o neste aparelho, diretamente do servidor da fazenda.</p>\';\nlogin.append(box);\nconst el=id=>document.getElementById(id);let busy=false;\nasync function check(){\nif(busy)return;busy=true;el(\'fsjInstallCheck\').disabled=true;\ntry{\n let allowed=false,message=\'Solicite autoriza\xe7\xe3o ao Propriet\xe1rio para liberar seu acesso.\';\n const response=await fetch(\'/api/me\',{credentials:\'same-origin\',cache:\'no-store\'});\n if(response.ok){const user=await response.json();allowed=!user.call_only;message=allowed?\'Conta autorizada. Instala\xe7\xe3o e atualiza\xe7\xf5es dispon\xedveis.\':\'Sess\xe3o restrita a chamada.\';}\n else if(response.status===401||response.status===403){\n  const token=localStorage.getItem(\'fsj_activation\');\n  if(token){const status=await fetch(\'/api/request-status\',{method:\'POST\',credentials:\'same-origin\',headers:{\'Content-Type\':\'application/json\',\'X-FSJ-Request\':\'1\'},body:JSON.stringify({activation:token})});\n   if(!status.ok)throw Error(\'N\xe3o foi poss\xedvel consultar este pedido. Use sua senha ou fale com o Propriet\xe1rio.\');\n   const data=await status.json();allowed=data.status===\'approved\'&&!data.expired;message=allowed?\'Autoriza\xe7\xe3o aprovada. Crie sua senha e instale o aplicativo.\':data.expired?\'Autoriza\xe7\xe3o expirada. Solicite renova\xe7\xe3o ao Propriet\xe1rio.\':\'Pedido aguardando libera\xe7\xe3o do Propriet\xe1rio.\';\n  }\n }else throw Error(\'Servidor indispon\xedvel. Tente consultar novamente.\');\n const android=/Android/i.test(navigator.userAgent),native=!!window.FSJAndroid;\n el(\'fsjInstallPackage\').hidden=!allowed||!android||native;\n el(\'fsjInstallUpdate\').hidden=!allowed;\n el(\'fsjInstallMessage\').textContent=message;\n el(\'fsjInstallHelp\').textContent=native?\'As telas v\xeam da VM. Novas vers\xf5es do Android s\xe3o verificadas pelo aplicativo e pedem confirma\xe7\xe3o para instalar.\':android?\'Ap\xf3s baixar, abra o APK e confirme Instalar. Se solicitado, permita esta fonte no Android.\':\'Este instalador \xe9 para Android. No iPhone, use a vers\xe3o web; n\xe3o h\xe1 pacote iOS nativo dispon\xedvel.\';\n}catch(error){el(\'fsjInstallPackage\').hidden=true;el(\'fsjInstallUpdate\').hidden=true;el(\'fsjInstallMessage\').textContent=error.message;}finally{busy=false;el(\'fsjInstallCheck\').disabled=false;}\n}\nel(\'fsjInstallRequest\').onclick=()=>document.getElementById(\'showRequest\')?.click();\nel(\'fsjInstallCheck\').onclick=check;\nel(\'fsjInstallUpdate\').onclick=async()=>{\n const button=el(\'fsjInstallUpdate\');button.disabled=true;\n try{const response=await fetch(\'/api/update-check\',{cache:\'no-store\',credentials:\'same-origin\'});if(!response.ok)throw Error(\'N\xe3o foi poss\xedvel solicitar a atualiza\xe7\xe3o.\');el(\'fsjInstallMessage\').textContent=\'Verifica\xe7\xe3o solicitada. Reabrindo a tela atualizada\u2026\';setTimeout(()=>location.reload(),2000);}catch(error){el(\'fsjInstallMessage\').textContent=error.message;button.disabled=false;}\n};\ndocument.addEventListener(\'fsj:session\',check);\ndocument.addEventListener(\'visibilitychange\',()=>{if(!document.hidden)check();});\n// Mesmo local de consulta ao voltar do cadastro, sem substituir o formul\xe1rio existente.\ndocument.getElementById(\'backLogin\')?.addEventListener(\'click\',check);\ncheck();\n})();\n'
from pathlib import Path
import datetime,shutil,os
p=Path.home()/'fsj-video-v001/static/app.js'
old=p.read_text()
if 'FSJ_INSTALL_CENTER_V1' in old:
 print('Central ja instalada. Feche e reabra o Reserva.');raise SystemExit(0)
if 'loginForm' not in old or 'fsj:session' not in old:raise SystemExit('Interface diferente. Nada alterado.')
new=old+'\n'+JS
backup=p.parent.parent/'backups'/('antes-central-instalacao-'+datetime.datetime.now().strftime('%Y%m%d-%H%M%S-%f')+'.js')
backup.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,backup)
tmp=p.with_name('app.js.central.tmp')
try:
 tmp.write_text(new);shutil.copymode(p,tmp);os.replace(tmp,p)
finally:tmp.unlink(missing_ok=True)
print('INSTALADO: central na tela de login. Feche e reabra o Reserva.')
print('Contas, banco, videos, chamadas e atualizacoes existentes preservados.')
print('Backup:',backup)
